import{z as n,x as M,o as E,c as s,q as o,j as t,D as a,d as r,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"DeepGEMM","description":"","frontmatter":{"title":"DeepGEMM","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/deepgemm.md","filePath":"llm/deepgemm.md","lastUpdated":1791413859000}'),A={name:"llm/deepgemm.md"};function d(B,e,m,c,h,P){const p=M("Mermaid");return E(),s("div",null,[e[2]||(e[2]=o('<h1 id="deepgemm" tabindex="-1">DeepGEMM <a class="header-anchor" href="#deepgemm" aria-label="Permalink to &quot;DeepGEMM&quot;">​</a></h1><div class="epigraph"><p>MoE 的专家层不是一张大方阵，而是许多形状随路由变化的分组 GEMM；核必须按当前 $(M,N,K)$ JIT 出来，并与 dispatch 后的 token 布局咬合。</p><footer>—— DeepSeek-AI，DeepGEMM：面向 FP8/BF16 与 MoE 的 Tensor Core 核库</footer></div><p>专家并行把 token 送到持有专家的 GPU 之后，本地计算是两层（或 SwiGLU 的门与上投影）矩阵乘。cuBLAS 擅长大方阵、稳定形状；MoE 一步里每个专家的 token 数 \\(M\\) 都在变，还有 FP8 缩放、掩码掉空槽、以及和通信重叠。DeepGEMM 是 DeepSeek 开源的 Tensor Core 核库：干净的 CUDA、运行时 JIT、覆盖 FP8/BF16（后续版本还扩展 FP4、Mega MoE 融合等），并明确让 <code>m_grouped_fp8_gemm_nt_masked</code> 一类接口吃 <a href="/llm/deepep">DeepEP</a> 低延迟核的输出。本篇写分组 GEMM 为什么不能当普通 BLAS 调；通信语义见 <a href="/llm/ep-all2all">EP All-to-All</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>V3 的 MoE 层：共享专家加 256 个路由专家，每 token 激活 8 个路由专家。落到一张卡上，是「若干专家、每个专家一段变长 token」。若把空槽 pad 成密集大矩阵再调一次 <code>gemm</code>，算力打在 padding 上，还多一次搬运。若对每个专家各调一次 cuBLAS，启动开销在解码的小 \\(M\\)（常常几十到二百）上压过有效 Tensor Core 时间。FP8 还要求缩放因子与 tile 对齐：V3 用细粒度 tile/block 量化，反量化必须藏进核，不能先还原成 BF16 再乘。</p><p>CUTLASS / CuTe 已经能写这类核，但模板代数重、编译慢。DeepGEMM 的设计叙事是：少而精的核心核、JIT 出当前形状、便于学习 Hopper 上的优化，而不是再包一层完整模板语言。它不是「发明了矩阵乘」，是把 V3 训练与推理真正用的那组形状和精度做成可复用库。</p><p><span class="marginnote">术语翻译：GEMM 就是通用矩阵乘法（GEneral Matrix Multiply）。普通调用是一张完整大矩阵乘另一张；「分组 GEMM」是把几十个小矩阵乘打包成一次调用——每个小组是「一个专家的权重 × 分给它的那批 token」，各组行数还不一样多。打包成一次调用是为了摊掉 GPU 上「启动一次计算」的固定开销。</span></p><h3 id="掩码分组而不是稠密填充" tabindex="-1">掩码分组而不是稠密填充 <a class="header-anchor" href="#掩码分组而不是稠密填充" aria-label="Permalink to &quot;掩码分组而不是稠密填充&quot;">​</a></h3><p>DeepEP dispatch 之后，本 rank 的缓冲往往仍按最大容量对齐，空位要掩掉。<code>m_grouped_fp8_gemm_nt_masked</code> 的名字写明三件事：沿 \\(M\\) 分组（每专家一段）、FP8、有掩码。调用方传入各组的有效长度，核在 Tensor Core 上只对有效 tile 提交 MMA。布局必须与通信核约定同一 permute，否则会出现「专家 A 的权重乘到专家 B 的 token」。这是系统契约，不是数值精度问题。</p><p><span class="marginnote">解码期每专家 \\(M\\) 小，核是访存墙：权重要从 HBM 读出，token 却不多。V3 因此让每卡少挂专家（解码甚至一卡一专家），使一次加载的权重能摊到该卡所有 token 上，并用少量 SM 跑 MoE，把 SM 留给 MLA。DeepGEMM 要在这种小 \\(M\\) 上仍然接近屋顶线，而不是只报训练时 8K token 的 TFLOPS。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="jit-与形状缓存" tabindex="-1">JIT 与形状缓存 <a class="header-anchor" href="#jit-与形状缓存" aria-label="Permalink to &quot;JIT 与形状缓存&quot;">​</a></h3><p>第一次碰到某组 \\((M,N,K)\\)、精度、对齐，JIT 编译核并缓存；之后同形状零额外编译。MoE 的 \\(M\\) 逐步变化，缓存命中取决于调度是否把 batch 修整到若干档（例如对齐 8/64）。完全动态的 \\(M\\) 会导致缓存爆炸与频繁编译，服务启动预热应覆盖常见档位。库强调安装时不必预编译全部 CUDA，降低分发成本，把代价挪到首次调用。</p><p><span class="marginnote">常见误区：初学者容易以为 JIT 编译一次就一劳永逸。实际上缓存按「形状+精度+对齐」精确匹配，\\(M\\) 从 37 变成 38 就可能触发重新编译——一次几十到上百毫秒，直接打进首 token 延迟。所以工程上要把 batch 尺寸「取整到档位」（如 64 的倍数），用少量档位换取缓存几乎全命中。</span></p><p>常规稠密 GEMM（注意力吸收后的投影、共享专家、非 MoE 层）走同一套 FP8/BF16 原语，便于整网同一量化故事。后续 Mega MoE 把 EP dispatch、第一层线性、SwiGLU、第二层线性、combine 收进更大核，与 NVLink 计算重叠——那是更激进的融合，依赖对称内存与多进程启动，不是所有引擎默认路径。写「我们用了 DeepGEMM」时应写清调用的是 grouped GEMM 还是 Mega 融合。</p><h3 id="与-deepep-的交接" tabindex="-1">与 DeepEP 的交接 <a class="header-anchor" href="#与-deepep-的交接" aria-label="Permalink to &quot;与 DeepEP 的交接&quot;">​</a></h3><p>低延迟 dispatch 的输出可能是按专家交错或按 rank 分段的特殊 layout。DeepGEMM 文档写明 grouped 接口的一个典型输入就是 DeepEP 低延迟核的输出。引擎不应在中间插 <code>contiguous()</code> 打回通用 NCHW，那会把通信与 GEMM 之间的带宽红利吃掉。反向训练还要把梯度 combine 回去，FP8 前向与 BF16 combine 的精度分界与 V3 报告一致。</p>',17)),(E(),t(i,null,{default:a(()=>[l(p,{id:"mermaid-49",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E8%B7%AF%E7%94%B1%E5%99%A8%20top-k%22%5D%20--%3E%20D%5B%22DeepEP%20dispatch%22%5D%0A%20%20D%20--%3E%20L%5B%22%E5%88%86%E7%BB%84%20FP8%20GEMM%20%E7%AC%AC%E4%B8%80%E5%B1%82%22%5D%0A%20%20L%20--%3E%20A%5B%22SwiGLU%20%E7%AD%89%E6%BF%80%E6%B4%BB%22%5D%0A%20%20A%20--%3E%20L2%5B%22%E5%88%86%E7%BB%84%20GEMM%20%E7%AC%AC%E4%BA%8C%E5%B1%82%22%5D%0A%20%20L2%20--%3E%20C%5B%22DeepEP%20combine%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="为什么-fp8-gemm-要和通信同一精度策略" tabindex="-1">为什么 FP8 GEMM 要和通信同一精度策略 <a class="header-anchor" href="#为什么-fp8-gemm-要和通信同一精度策略" aria-label="Permalink to &quot;为什么 FP8 GEMM 要和通信同一精度策略&quot;">​</a></h3><p>V3 在 MoE 上投影前把激活量化成 FP8 再 dispatch，使链路上的字节与 Tensor Core 输入一致，避免「BF16 传输、到卡再量化」。缩放因子取 2 的幂等约定，是为了反量化乘成移位。DeepGEMM 的 FP8 核必须理解同一套 scale 布局（tile 级或 block 级），否则数值与训练图分叉。combine 保持 BF16，是因为加权求和与残差对误差更敏感。库若只提供「FP8 乘 FP8 出 FP8」而引擎在 combine 前乱转精度，报告中的稳定训练叙事无法复现。</p><p>分组核的并行轴是专家（组）× tile。负载不均时，热专家的 \\(M\\) 大、冷专家的 \\(M\\) 近 0，SM 利用率被热组限制。这再次把问题交回路由与冗余专家，而不是再写一个更聪明的 GEMM。</p><p><span class="marginnote">H100/H800 的 FP8 Tensor Core 峰值很高，但 MoE 的有效 TFLOPS 常远低于峰值，因为 \\(M\\) 小、scale 反量化、以及通信占用 SM。对比 cuBLAS 的公平方式是：同一 grouped 形状、同一 FP8 布局、含或不含 mask 一致。不要用方阵 FP8 峰值宣传 MoE 加速比。</span></p><p>256 个专家、每个只分到几十个 token 时，三种组织方式的有效算力差距巨大——这张对照回答「为什么必须分组」：</p>',6)),(E(),t(i,null,{default:a(()=>[l(p,{id:"mermaid-68",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%8F%98%E9%95%BF%E7%9A%84%E6%AF%8F%E4%B8%93%E5%AE%B6%20token%20%E6%AE%B5%22%5D%20--%3E%20A%5B%22%E6%96%B9%E5%BC%8F%E4%B8%80%EF%BC%9Apad%20%E6%88%90%E7%A8%A0%E5%AF%86%E5%A4%A7%E7%9F%A9%E9%98%B5%22%5D%0A%20%20M%20--%3E%20B%5B%22%E6%96%B9%E5%BC%8F%E4%BA%8C%EF%BC%9A%E6%AF%8F%E4%B8%93%E5%AE%B6%E5%8D%95%E7%8B%AC%E8%B0%83%20cuBLAS%22%5D%0A%20%20M%20--%3E%20C%5B%22%E6%96%B9%E5%BC%8F%E4%B8%89%EF%BC%9A%E5%88%86%E7%BB%84%E6%A0%B8%EF%BC%8C%E5%8F%AA%E6%8F%90%E4%BA%A4%E6%9C%89%E6%95%88%20tile%22%5D%0A%20%20A%20--%3E%7C%22%E7%A9%BA%E6%A7%BD%E4%B9%9F%E7%AE%97%22%7C%20PA%5B%22%E7%AE%97%E5%8A%9B%E7%83%A7%E5%9C%A8%20padding%20%E4%B8%8A%22%5D%0A%20%20B%20--%3E%7C%22%E7%99%BE%E6%AC%A1%E5%B0%8F%E6%A0%B8%E5%90%AF%E5%8A%A8%22%7C%20PB%5B%22%E5%90%AF%E5%8A%A8%E5%BC%80%E9%94%80%E5%8E%8B%E8%BF%87%E8%AE%A1%E7%AE%97%22%5D%0A%20%20C%20--%3E%7C%22mask%20%E6%8E%89%E7%A9%BA%E4%BD%8D%20%2B%20%E4%B8%80%E6%AC%A1%E8%B0%83%E7%94%A8%22%7C%20PC%5B%22%E6%8E%A5%E8%BF%91%20Tensor%20Core%20%E5%B1%8B%E9%A1%B6%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<p><span class="marginnote">数字实例：假设 8 个专家各分到约 32 个 token。方式一把它们 pad 成满员的 256×行矩阵，约九成的乘法算在空槽上；方式二发 8 次（实际生产常是上百次）核启动，每次开销几十微秒、有效计算却只有几微秒。分组核一次调用、只算有效 tile，两头都省——这就是那句「启动开销在解码的小 \\(M\\) 上压过有效 Tensor Core 时间」的具体含义。</span></p><h3 id="与-cutlass-生态的位置" tabindex="-1">与 CUTLASS 生态的位置 <a class="header-anchor" href="#与-cutlass-生态的位置" aria-label="Permalink to &quot;与 CUTLASS 生态的位置&quot;">​</a></h3><p>DeepGEMM 借用 CUTLASS/CuTe 的一些概念（TMA、warpgroup MMA、pipeline），但避免重度模板。对学习核优化，仓库比从 CUTLASS 例子里抽 MoE 路径更短。生产上，有的栈继续用 CUTLASS 或供应商 BLAS；有的栈（SGLang 等）接 DeepGEMM。性能数字必须绑 GPU 代际：Ampere 无硬件 FP8，不是目标硬件。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>JIT 首次延迟会进冷启动 TTFT，预热或持久化编译缓存是必须的。形状未对齐时的正确性（mask、scale 广播、专家下标与权重行的对应）比再抠 1% TFLOPS 更要紧。一次 layout 错位会表现为「MoE 层输出分布漂、但损失看起来还在降」，极难查。Mega MoE 把 dispatch 到 combine 收进同一核，上限更高，Nsight 上却更难把通信与 MMA 拆开；未稳定前应先跑分离的 DeepEP + grouped GEMM 路径。</p><p>不要把 DeepGEMM 写成「替代 FlashAttention」：注意力走 <a href="/llm/flashmla">FlashMLA</a>，专家 MLP 走这里。也不要在 Ampere 上期待同一套 FP8 核。共享专家与路由专家的形状不同，可能要两次调用，不要强行填进同一 grouped 批次里却忘了共享专家不过路由。数值对照应以 V3 报告的细粒度 FP8 策略为准：tile 或 block 的 scale 不能随手改成逐张量一条 scale。</p><p>出处：DeepSeek-AI，<em>DeepGEMM</em>，<a href="https://github.com/deepseek-ai/DeepGEMM%EF%BC%9B%E7%B2%BE%E5%BA%A6%E4%B8%8E" target="_blank" rel="noreferrer">https://github.com/deepseek-ai/DeepGEMM；精度与</a> MoE 布局见 <em>DeepSeek-V3 Technical Report</em>，arXiv:2412.19437。CUTLASS 是 NVIDIA 的独立项目。不要伪造 DeepGEMM 的会议论文号。</p><p><span class="marginnote">版本演进快（FP4、PDL、更快 JIT）。引用应带 git 修订或发布日期，以及调用的 API 名。2025 年的 grouped FP8 说明不能自动覆盖 2026 年的 Mega MoE 路径。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DeepGEMM 为变长分组、FP8 缩放和掩码空槽提供 Tensor Core 核，对准 MoE 专家层。</li><li>与 DeepEP 的 layout 契约比「调 GEMM」本身更关键。</li><li>JIT 按形状缓存；服务要预热常见 \\(M\\)。</li><li>小 \\(M\\) 解码是访存墙，需与一卡少专家、少通信 SM 的部署一致。</li><li>出处：deepseek-ai/DeepGEMM；DeepSeek-V3 报告。</li></ul>',10))])}const u=n(A,[["render",d]]);export{F as __pageData,u as default};
